using System;using System.Collections.Generic;using System.Linq;using UnityEngine;using UnityEngine.InputSystem;using UnityEngine.InputSystem.Controls;
// Device events collect without a grace timer; Read is the 60Hz logical-frame boundary.
public sealed class TrainingDeviceInput {
 sealed class Device {public int held,pressed;public bool t1,t2,pressedT1,pressedT2;public readonly ModifierPressOwnership ownership=new ModifierPressOwnership();}
 readonly Dictionary<int,Device> devices=new Dictionary<int,Device>();readonly List<TrainingCommand> commands=new List<TrainingCommand>();readonly HashSet<InputControl> forceControls=new HashSet<InputControl>();readonly bool second;readonly TrainingInputConfig config;TrainingInputFrame input;bool neutral;public InputActionMap Map{get;private set;}public string Error{get;private set;}
 Device Get(int id){if(!devices.TryGetValue(id,out var d)){d=new Device();Array.Copy(config.modifier1Actions,d.ownership.t1,9);Array.Copy(config.modifier2Actions,d.ownership.t2,9);devices[id]=d;}return d;}
 public TrainingDeviceInput(TrainingInputConfig c,bool secondPlayer){second=secondPlayer;config=c;Map=new InputActionMap(second?"Battle-2P-v3":"Battle-1P-v3");if(!c.ValidateV3(out var error)){Error=error;throw new ArgumentException(error);}var move=Map.AddAction("Move",InputActionType.Value);var composite=move.AddCompositeBinding("2DVector(mode=1)");composite.With("Up",second?"<Keyboard>/numpad8":"<Keyboard>/w").With("Down",second?"<Keyboard>/numpad5":"<Keyboard>/s").With("Left",second?"<Keyboard>/numpad4":"<Keyboard>/a").With("Right",second?"<Keyboard>/numpad6":"<Keyboard>/d");if(!second){move.AddCompositeBinding("2DVector(mode=1)").With("Up","<Keyboard>/upArrow").With("Down","<Keyboard>/downArrow").With("Left","<Keyboard>/leftArrow").With("Right","<Keyboard>/rightArrow");Add(move,c.firstMoveStickGamepadBinding);Add(move,c.firstMoveDpadGamepadBinding);}move.performed+=ctx=>{var v=ctx.ReadValue<Vector2>();if(v.y>.5f&&input.Movement.y<=.5f)commands.Add(TrainingCommand.Jump);input.Movement=v;};move.canceled+=ctx=>input.Movement=Vector2.zero;
  var keys=c.SlotKeys(second);for(int i=0;i<9;i++){int slot=i;var a=Map.AddAction(((BattleAttackSlot)i).ToString(),InputActionType.PassThrough);Add(a,keys[i]);if(!second)Add(a,c.slotGamepadBindings[i]);a.performed+=ctx=>{var d=Get(ctx.control.device.deviceId);int bit=1<<slot;if(ctx.ReadValue<float>()>.5f){if((d.held&bit)==0)d.pressed|=bit;d.pressedT1|=d.t1;d.pressedT2|=d.t2;d.held|=bit;}else d.held&=~bit;};}
  if(!second){Modifier("T1",c.modifier1Binding,1);Modifier("T2",c.modifier2Binding,2);}
  Pulse("Hold",second?c.secondThrowKeyboardBinding:c.firstThrowKeyboardBinding,"",()=>commands.Add(TrainingCommand.Throw));Pulse("TRC",second?c.secondTrcKeyboardBinding:"<Keyboard>/semicolon",second?"":c.trcGamepadBinding,()=>commands.Add(TrainingCommand.Cancel));
  var force=Map.AddAction("Mania",InputActionType.PassThrough);if(!second){Add(force,"<Keyboard>/leftShift");Add(force,"<Keyboard>/rightShift");Add(force,c.maniaGamepadBinding);}force.performed+=ctx=>{if(ctx.ReadValue<float>()>.5f)forceControls.Add(ctx.control);else forceControls.Remove(ctx.control);};
  var dash=Map.AddAction("Dash",InputActionType.Button,second?"<Keyboard>/numpad0":"<Keyboard>/space");dash.performed+=ctx=>{input.Dash=true;input.DashPressed=true;};dash.canceled+=ctx=>input.Dash=false;
  if(!second){Pulse("Record","<Keyboard>/r",c.recordGamepadBinding,()=>input.RecordPressed=true);Pulse("Play","<Keyboard>/p",c.playGamepadBinding,()=>input.PlayPressed=true);Pulse("Reset","<Keyboard>/leftCtrl","<Keyboard>/rightCtrl",()=>input.Reset=true);}
  InputSystem.onDeviceChange+=DeviceChanged;
 }
 void Modifier(string name,string binding,int modifier){if(string.IsNullOrWhiteSpace(binding))return;var a=Map.AddAction(name,InputActionType.PassThrough,binding);a.performed+=ctx=>{var d=Get(ctx.control.device.deviceId);if(modifier==1){d.t1=ctx.ReadValue<float>()>.5f;d.pressedT1|=d.t1;}else{d.t2=ctx.ReadValue<float>()>.5f;d.pressedT2|=d.t2;}};}
 static void Add(InputAction a,string binding){if(!string.IsNullOrWhiteSpace(binding))a.AddBinding(binding);}
 void Pulse(string name,string key,string pad,Action action){var a=Map.AddAction(name,InputActionType.PassThrough);Add(a,key);Add(a,pad);a.performed+=ctx=>{if(ctx.ReadValue<float>()>.5f)action();};}
 public TrainingInputFrame Read(bool training){
  if(neutral){bool held=Map.actions.Any(a=>a.controls.OfType<ButtonControl>().Any(c=>c.isPressed))||Map["Move"].ReadValue<Vector2>().sqrMagnitude>.01f;ClearPending();if(!held)neutral=false;return default;}
  var result=input;result.ForceHeld=forceControls.Count>0;result.AttackPressedMask=result.AttackHeldMask=0;bool dashOwned=false;
  foreach(var d in devices.Values){var resolved=d.ownership.SampleAtBoundary(d.held,d.pressed,d.t1||d.pressedT1,d.t2||d.pressedT2,d.t1,d.t2,training);result.AttackPressedMask|=resolved.attackMask;result.AttackHeldMask|=d.held;result.ForceHeld|=resolved.forceHeld;result.Dash|=resolved.dashHeld;foreach(var action in resolved.pulses){switch(action){case ModifiedInputAction.A:case ModifiedInputAction.B:case ModifiedInputAction.C:case ModifiedInputAction.X:case ModifiedInputAction.Y:case ModifiedInputAction.Z:result.AttackPressedMask|=1<<((int)action-1);break;case ModifiedInputAction.J:case ModifiedInputAction.K:case ModifiedInputAction.L:result.AttackPressedMask|=1<<(6+(int)action-(int)ModifiedInputAction.J);break;case ModifiedInputAction.TRC:commands.Add(TrainingCommand.Cancel);break;case ModifiedInputAction.Throw:commands.Add(TrainingCommand.Throw);break;case ModifiedInputAction.Dash:result.DashPressed=true;result.Dash=true;break;case ModifiedInputAction.Record:result.RecordPressed=true;break;case ModifiedInputAction.Play:result.PlayPressed=true;break;case ModifiedInputAction.Reset:result.Reset=true;break;}}d.pressed=0;d.pressedT1=d.pressedT2=false;}
  result.Commands=commands.ToArray();commands.Clear();input.DashPressed=input.Reset=input.RecordPressed=input.PlayPressed=false;if(!training)result.Reset=result.RecordPressed=result.PlayPressed=false;return result;
 }
 void ClearPending(){input=default;commands.Clear();forceControls.Clear();devices.Clear();}
 public void Clear(){ClearPending();neutral=true;}
 void DeviceChanged(InputDevice device,InputDeviceChange change){if(change==InputDeviceChange.Removed||change==InputDeviceChange.Disconnected||change==InputDeviceChange.Disabled)Clear();}
 public void Detach(){InputSystem.onDeviceChange-=DeviceChanged;}
}
